from author_main import SECTIONS,section,w,pareto,key,trap
from author_popups import table
SECTIONS['e-1']=section('e-1','e-1','Hiérarchie des examens : indication et question',
'''<p>La référence diagnostique est l’analyse spécialisée d’un prélèvement adapté, intégrée au contexte. Pour un lymphome nodal, la biopsie excisionnelle/incisionnelle préserve l’architecture ; pour le BPDCN leucémique, le sang et la moelle avec cytométrie peuvent contribuer directement au diagnostic. « Biopsie » ne signifie donc pas le même geste pour toute la rubrique C86.</p>'''+table(['Examen','Quand et pourquoi','Limites'],[
[w('c86-biopsie','Tissu et immunohistochimie'),'Établir l’entité, selon le siège.','Nécrose, petite carotte ou traitement préalable peuvent réduire le rendement ; demander une nouvelle preuve si discordance.'],
[w('c86-tcr','Clonalité TCR'),'Question de lignée/clonalité en complément.','Clones réactifs possibles ; résultat négatif possible dans une tumeur.'],
[w('c86-tep','TEP-TDM'),'Extension et réponse des PTCL systémiques avides.','Pas un examen diagnostique histologique ; inflammation et infection peuvent fixer. Pas systématique dans la LyP typique sans autre anomalie.'],
[w('c86-moelle','Moelle'),'Bilan des PTCL systémiques ; particulièrement important dans HSTL et BPDCN.','Pas automatiquement requise dans les proliférations cutanées indolentes sans autre signe.'],
[w('c86-ebv','ADN d’EBV plasmatique'),'Pronostic et suivi dans ENKTL.','Ne remplace pas EBER tissulaire ; prélèvement et méthode constants pour comparer.'],
[w('c86-bio','Biologie et préparation'),'Hémogramme, organes, LDH, virologie pertinente et bilan avant traitement.','LDH non spécifique ; intervalles propres au laboratoire et seuils de décision distincts.'],
['Exploration digestive','Biopsies, entéroscopie, entéro-imagerie et capsule selon RCD-II/EATL.','Évaluer le risque de rétention avant capsule chez un patient à risque de sténose ; la capsule ne prélève pas le tissu.'],
['Liquide cérébrospinal dans BPDCN','Consensus spécialisé : évaluation initiale et stratégie du SNC selon présentation.','Une ponction s’organise en tenant compte de la sécurité clinique et hématologique ; ce n’est pas un dépistage indifférencié de tout C86.'],
['TDM/TEP en rémission asymptomatique','Pas de surveillance systématique recommandée pour les PTCL en rémission complète.','Un nouveau signe justifie une réévaluation ciblée.']])+
key('Avant chaque examen, formuler la question. Un résultat utile à l’extension ne prouve pas l’entité, et un score pronostique ne remplace pas le diagnostic.'),'ESMO25','CUT18','BPDCN23','TSE','ESsCD26','ESGE22')
SECTIONS['e-2']=section('e-2','e-2','Interpréter les nombres : normalité, critère et seuil d’action',
'''<p>Un intervalle de référence décrit une population et une méthode ; un seuil diagnostique ou thérapeutique répond à une autre question. Le support d’enseignement HUG de septembre 2019 présente, chez l’adulte, Hb 140–180 g/L chez l’homme et 120–160 g/L chez la femme, leucocytes 4–11 G/L et plaquettes 150–350 G/L. Ce sont des repères suisses datés, pas des normes nationales 2026 ni des valeurs pédiatriques ou de grossesse. Le compte rendu actuel du laboratoire du patient prévaut.</p>'''+table(['Paramètre','Valeur et fonction','Piège'],[
['Hb, plaquettes, neutrophiles en HLH-2004','Cytopénies de ≥2 lignées : Hb <90 g/L, plaquettes <100 G/L, neutrophiles <1 G/L, avec particularité néonatale pour Hb.','Seuil de critère HLH ; pas définition générale de toute anémie, ni seuil transfusionnel.'],
['Ferritine','≥500 µg/L parmi les critères HLH-2004.','Très peu spécifique seule chez l’adulte ; interpréter dynamique, organes et autres critères.'],
['CD30','≥75 % des cellules tumorales dans les critères pcALCL ; ≥10 % à l’inclusion d’ECHELON-2.','Ces deux nombres répondent à des questions différentes et ne suffisent ni au diagnostic ni à la décision de traitement.'],
['TFH','CD4 + au moins deux marqueurs du panel, dans la morphologie appropriée.','Un phénotype TFH peut exister dans des cellules normales/réactives.'],
['RCD-II','Cellules intraépithéliales aberrantes typiquement ≥20 % par cytométrie.','Contexte symptomatique, régime ≥12 mois, atrophie, exclusion des alternatives et clonalité intégrés.'],
['Albumine, première dose Elzonris','≥3,2 g/dL, soit ≥32 g/L.','Prérequis de traitement, non borne universelle de normalité.'],
['Albumine sous Elzonris','<3,5 g/dL ou baisse ≥0,5 g/dL : action selon algorithme de fuite capillaire.','À surveiller avant les doses ; seuil différent de celui de démarrage.'],
['Poids sous Elzonris','Hausse ≥1,5 kg par rapport au poids avant la dose précédente.','Un changement rapide peut signaler la fuite capillaire ; ne pas le confondre avec une prise de poids nutritionnelle.']])+
'''<p><b>Calcul fictif.</b> Sur 200 cellules tumorales comptées, 160 positives donnent (160 ÷ 200) ×100 =80 %. Cela satisfait le seuil numérique CD30 du pcALCL, mais le diagnostic exige encore morphologie, contexte et extension. De même, une albumine passant de 3,8 à 3,3 g/dL baisse de 0,5 g/dL : elle franchit un seuil d’action sous tagraxofusp bien que 3,3 reste supérieur à 3,2. La comparaison au seul seuil de première dose serait une erreur.</p>'''+w('c86-index','Calcul des index et variables nécessaires')+trap('Un chiffre ne se lit jamais sans sa population, son unité, sa méthode et sa finalité.'),'HUG','HLH19','HLH23','KEMPF','OMS22','ESsCD26','ELZONRIS','ADCETRIS')
SECTIONS['e-3']=section('e-3','e-3','Imagerie, endoscopie et bilan d’extension',
'''<p>La TEP au FDG montre un métabolisme augmenté, qui peut être tumoral ou inflammatoire. Environ 10 % des PTCL sont peu ou pas avides dans les données discutées par ESMO ; une TEP négative ne remplace pas une moelle ou un prélèvement indiqué. L’examen initial sert aussi de référence pour la réponse. Les critères d’extension des lymphomes systémiques ne s’appliquent pas mécaniquement aux lymphomes cutanés primitifs.</p>'''+table(['Entité','Parcours d’extension','Interprétation'],[
['ENKTL','TEP-TDM ; imagerie ORL adaptée, notamment IRM selon extension ; bilan médullaire et évaluation du SNC selon risque/signes.','ADN d’EBV plasmatique et réponse métabolique se complètent. Une valeur Deauville ≤3 traduit une réponse métabolique complète dans le cadre utilisé.'],
['HSTL','Foie, rate et moelle ; TEP-TDM selon parcours.','La réponse de la moelle et, lorsque possible/pertinent, du foie se confirme par prélèvement dans la recommandation. Le volume splénique seul ne décrit pas toute la réponse.'],
['RCD-II/EATL','Biopsies, TEP, entéro-IRM et exploration endoscopique adaptée.','La capsule visualise sans biopsier. ESGE demande de prendre en compte le risque de rétention dans une suspicion de tumeur du grêle ; obstruction ou sténose modifient le parcours.'],
['LyP typique','Examen clinique et biologie adaptée ; imagerie si signes d’extension ou présentation atypique.','Une LyP diffuse ne devient pas automatiquement un lymphome systémique de stade IV.'],
['pcALCL','TDM thoraco-abdomino-pelvienne ± TEP, exploration des ganglions suspects.','La moelle est conditionnelle si maladie limitée à la peau. La stadification cutanée décrit T, N et M avec leur contexte.'],
['BPDCN','Peau, sang/moelle, ganglions et organes selon symptômes ; évaluation du SNC selon consensus.','Une réponse cutanée ne prouve pas à elle seule une rémission médullaire ou neurologique.']])+
'''<p>L’ESGE 2022 ne demande pas des investigations préalables identiques avant toute capsule pour suspicion tumorale ; elle les réserve notamment aux personnes à risque de rétention. Les recommandations de capsule de perméabilité dans Crohn ont leur propre population et ne sont pas transposées comme règle automatique à chaque EATL. Le gastroentérologue choisit la modalité qui peut répondre à la question sans majorer le risque.</p>'''+w('c86-stad-cutanee','Stadification des proliférations cutanées'),'ESMO25','TSE','CUT18','KEMPF','ESsCD26','ESGE22','BPDCN23')
SECTIONS['e-4']=section('e-4','e-4','Lire l’immunophénotype sans transformer un marqueur en diagnostic',
table(['Entité','Profil utile','Réserve indispensable'],[
['ENKTL','EBER dans cellules tumorales ; phénotype cytotoxique, souvent CD56 ; forme NK typiquement CD3 de surface négatif/CD3ε cytoplasmique positif.','Des formes de lignée T existent et peuvent réarranger TCR. Le profil NK n’est pas obligatoire dans chaque ENKTL.'],
['HSTL','TCR souvent gamma-delta, parfois alpha-bêta ou silencieux ; infiltration sinusoïdale ; i(7q) possible.','Ne pas additionner 75 %, 25 % et 5 % issus d’approximations comme une répartition exhaustive à 105 %.'],
['EATL et RCD-II','Étude du tissu intestinal, lymphocytes aberrants et clonalité ; anomalies JAK/STAT décrites.','RCD-II n’est pas synonyme de lymphome constitué. MEITL reste une entité séparée.'],
['SPTCL','CD3, CD8 et marqueurs cytotoxiques, TCR alpha-bêta/βF1 ; rimming adipocytaire.','Confronter au lupus et aux autres lymphomes ; HAVCR2 n’est pas une condition diagnostique obligatoire.'],
['BPDCN','CD123, TCF4/TCL1/CD303/CD304 selon panel ; CD4 et/ou CD56 ; exclusions de lignée.','Lire les combinaisons exactes OMS, pas une liste de quatre marqueurs tous obligatoires.'],
['nTFHL-AI','CD4 et marqueurs TFH ; réseau stromal, vaisseaux et architecture ; TET2/DNMT3A/RHOA/IDH2 peuvent contribuer.','Une petite carotte peut permettre « lymphome TFH nodal » sans autoriser le sous-type architectural précis.'],
['pcALCL et LyP','CD30 ; contexte clinique, architecture et évolution.','DUSP22 dans le pcALCL n’a pas automatiquement le même sens pronostique que dans l’ALCL systémique.']])+
key('Le compte rendu explique ce qui soutient le diagnostic, ce qui l’exclut et ce qui reste incertain. Une discussion clinico-pathologique résout les discordances mieux qu’un automatisme fondé sur un marqueur.'),'OMS22','OMS-DC','ESMO25','WHO-CUT','MOONLA','ESsCD26')
def quiz(title,question,answers,explain):
 return '<div class="quiz ui"><p><b>'+title+'</b> '+question+'</p>'+''.join(f'<button data-ok="{int(i==0)}">{txt}</button>' for i,txt in enumerate(answers))+'<p class="fb" hidden>'+explain+'</p></div>'
SECTIONS['e-5']=section('e-5','e-5','Cas cliniques pour vérifier le raisonnement',
'''<p>Vignettes fictives : choisir une réponse puis lire l’explication. Les indices sont intégrés au contexte, sans remplacer une décision clinique réelle.</p>'''+
quiz('Cas 1 — nez','Une biopsie d’ulcère palatin montre un infiltrat compatible, EBER dans les cellules tumorales et phénotype cytotoxique NK. Quel couple est cohérent ?', ['A. ENKTL ; suivi de l’ADN d’EBV plasmatique avec la réponse clinique et métabolique.','B. LyP ; sérologie EBV seule pour mesurer la tumeur.','C. HSTL ; CHOP automatique.'],'Réponse A. L’ensemble tissu–EBV–phénotype soutient ENKTL. La sérologie EBV isolée ne prouve pas la tumeur et l’ADN plasmatique n’en remplace pas la biopsie.')+
quiz('Cas 2 — peau','Des papules régressent spontanément par poussées, avec une biopsie compatible avec LyP et aucun signe systémique. Quelle conclusion est correcte ?', ['A. La corrélation clinique–histologique guide un parcours cutané ; une diffusion cutanée n’est pas automatiquement un stade IV systémique.','B. Toutes les lésions CD30 positives exigent BV-CHP.','C. Une TEP et une moelle sont obligatoires dans toute LyP typique.'],'Réponse A. Chronologie et absence de signe d’extension évitent une stadification ou un traitement excessif. Le suivi reste nécessaire pour les lymphomes associés.')+
quiz('Cas 3 — biologie','Sous Elzonris, l’albumine passe de 3,8 à 3,3 g/dL avec gain rapide de poids. Quelle lecture est correcte ?', ['A. Suspecter une fuite capillaire et appliquer l’algorithme de suspension/prise en charge de la FI.','B. Poursuivre sans réévaluation car 3,3 dépasse le seuil de démarrage de 3,2.','C. Attendre le sixième jour, date obligatoire de survenue.'],'Réponse A. Le seuil sous traitement est distinct : albumine <3,5 ou baisse ≥0,5 g/dL. Le tableau clinique renforce l’alerte ; la médiane de six jours n’est pas un calendrier de sécurité.')+
quiz('Cas 4 — intestin','Une personne cœliaque reste symptomatique avec atrophie après au moins douze mois de régime vérifié ; une population intraépithéliale aberrante est documentée. Quelle démarche est correcte ?', ['A. Confirmer RCD-II par l’ensemble des données, exclure EATL et alternatives, puis organiser le suivi expert.','B. Appeler automatiquement tout clone un EATL.','C. Attribuer le risque de transformation de RCD-II à toutes les personnes cœliaques.'],'Réponse A. Symptômes, régime, histologie, cytométrie et clonalité s’interprètent ensemble. Une complication aiguë impose une évaluation urgente indépendante du rythme programmé.')+
pareto('examens','Examens et interprétation'),'ESMO25','TSE','KEMPF','ELZONRIS','ESsCD26')
